BEGIN TRANSACTION;
CREATE TABLE terminal_fano_fourfolds_index1_200 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    Equation_degree INTEGER NOT NULL CHECK (Equation_degree <= 200),
    a1 INTEGER NOT NULL,
    a2 INTEGER NOT NULL,
    a3 INTEGER NOT NULL,
    a4 INTEGER NOT NULL,
    a5 INTEGER NOT NULL,
    a6 INTEGER NOT NULL,
    CanonicalClass INTEGER NOT NULL,
    Degree TEXT NOT NULL,
    Degree_dec REAL NOT NULL,
    Point_Basket TEXT,
    Point_Basket_size INTEGER,
    Curve_Basket TEXT,
    Curve_Basket_size INTEGER,
    Surface_Basket TEXT,
    Surface_Basket_size INTEGER,
    IsSmooth INTEGER CHECK (IsSmooth IN (0, 1)),
    IsQsmooth INTEGER NOT NULL CHECK (IsQsmooth IN (0, 1)),
    IsTerminal INTEGER NOT NULL CHECK (IsTerminal IN (0, 1)),
    IsCanonical INTEGER NOT NULL CHECK (IsCanonical IN (0, 1)),
    UNIQUE (a1, a2, a3, a4, a5, a6)
);
CREATE INDEX idx_exhaustive_degree ON terminal_fano_fourfolds_index1_200(Equation_degree);
CREATE INDEX idx_exhaustive_qsmooth ON terminal_fano_fourfolds_index1_200(IsQsmooth);
CREATE INDEX idx_exhaustive_degree_dec ON terminal_fano_fourfolds_index1_200(Degree_dec);
DELETE FROM "sqlite_sequence";
COMMIT;
